#[derive(Clone, Debug)]
pub struct DeviceClient {
    list: NativeRequestHandle<DeviceList>,
    observe: NativeRequestHandle<DeviceObserve>,
    set_trust: NativeRequestHandle<DeviceSetTrust>,
}
impl DeviceClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn list(&self, request: ListRequest) -> Result<ListResponse, DeviceListInvocationError> {
        self.list.invoke(LIST_OPERATION, request).await
            .map_err(DeviceListInvocationError::Runtime)?
            .map_err(DeviceListInvocationError::Domain)
    }

    pub async fn list_with_context(&self, context: InvocationContext, request: ListRequest) -> Result<ListResponse, DeviceListInvocationError> {
        self.list.invoke_with_context(LIST_OPERATION, context, request).await
            .map_err(DeviceListInvocationError::Runtime)?
            .map_err(DeviceListInvocationError::Domain)
    }

    pub async fn observe(&self, request: ObserveRequest) -> Result<ObserveResponse, DeviceObserveInvocationError> {
        self.observe.invoke(OBSERVE_OPERATION, request).await
            .map_err(DeviceObserveInvocationError::Runtime)?
            .map_err(DeviceObserveInvocationError::Domain)
    }

    pub async fn observe_with_context(&self, context: InvocationContext, request: ObserveRequest) -> Result<ObserveResponse, DeviceObserveInvocationError> {
        self.observe.invoke_with_context(OBSERVE_OPERATION, context, request).await
            .map_err(DeviceObserveInvocationError::Runtime)?
            .map_err(DeviceObserveInvocationError::Domain)
    }

    pub async fn set_trust(&self, request: SetTrustRequest) -> Result<SetTrustResponse, DeviceSetTrustInvocationError> {
        self.set_trust.invoke(SET_TRUST_OPERATION, request).await
            .map_err(DeviceSetTrustInvocationError::Runtime)?
            .map_err(DeviceSetTrustInvocationError::Domain)
    }

    pub async fn set_trust_with_context(&self, context: InvocationContext, request: SetTrustRequest) -> Result<SetTrustResponse, DeviceSetTrustInvocationError> {
        self.set_trust.invoke_with_context(SET_TRUST_OPERATION, context, request).await
            .map_err(DeviceSetTrustInvocationError::Runtime)?
            .map_err(DeviceSetTrustInvocationError::Domain)
    }
}

impl CapabilityClient for DeviceClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            list: dependencies.one::<DeviceList>()?,
            observe: dependencies.one::<DeviceObserve>()?,
            set_trust: dependencies.one::<DeviceSetTrust>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for DeviceClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    list: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<DeviceList>()?,
                    observe: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<DeviceObserve>()?,
                    set_trust: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<DeviceSetTrust>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum DeviceListInvocationError {
    Domain(ListError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum DeviceObserveInvocationError {
    Domain(ObserveError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum DeviceSetTrustInvocationError {
    Domain(SetTrustError),
    Runtime(RuntimeFailure),
}
